    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address _owner) internal {
        vm.assume(true);
        bool success;
        try c.setOwner(_owner) returns (bool __r) { success = __r; } catch { return; }
        assertTrue(success && c.owner() == _owner);
    }

    function testFuzz_run(address _owner) public {
